mapper.update:
update message
set status = 2
where conversation_id = #{conversationId}
and status = 1
and receiver_id = #{userId}

update conversation
set last_message = #{lastMessage},
    last_message_time = #{now},
    last_message_type = #{type},
    updated_time = #{now}
where id = #{conversationId}

update group_user
set unread_count = 0,last_read_message_id = #{lastReadMessageId}
where group_id = #{groupId}
  and user_id = #{userId}
and last_read_message_id < #{lastReadMessageId}

update `group`
set last_message = #{content},
    last_message_time = #{now},
    last_message_type = #{type},
    updated_time = #{now}
where id = #{groupId}

UPDATE group_user
SET unread_count = unread_count + 1
WHERE group_id = #{groupId}
  AND user_id != #{senderId}

mapper.select:
select c.id as id, c.user1_id as user1Id, c.user2_id as user2Id, c.last_message as lastMessage, c.last_message_time as lastMessageTime, c.last_message_type as lastMessageType, c.unread_count_user1 as unreadCountUser1, c.unread_count_user2 as unreadCountUser2, c.created_time as createdTime, c.updated_time as updatedTime from conversation c where (c.user1_id = #{userId} or c.user2_id = #{userId})
and (c.updated_time < #{lastTime} or (c.updated_time = #{lastTime} and c.id < #{lastId}))
order by c.updated_time desc,c.id desc limit #{limit}

select m.id as messageId, m.sender_id as senderId, m.content as content, m.type as type, m.status as status, m.created_time as createdTime from message m where m.conversation_id = #{conversationId} and (m.sender_id = #{userId} or m.receiver_id = #{userId})
and m.id < #{lastId}
order by m.id desc limit #{limit}

select g.id as groupId, g.owner_id as ownerId, g.avatar_url as groupAvatarUrl, g.name as groupName, g.signature as signature, g.member_count as memberCount, g.last_message as lastMessage, g.last_message_type as lastMessageType, g.last_message_time as lastMessageTime, g.status as status, g.created_time as createdTime, g.updated_time as updatedTime from `group` g where g.id in
#{id}
and (g.updated_time < #{lastTime} or (g.updated_time = #{lastTime} and g.id < #{lastId}))
order by g.updated_time desc,g.id desc limit #{limit}

select id as messageId, group_id as groupId, sender_id as senderId, content as content, type as type, is_recalled as isRecalled, created_time as createdTime from group_message where group_id = #{groupId}
and id < #{lastId}
order by id desc limit #{limit}

select u.id as userId,
       u.avatar_url as avatarUrl
from group_user gu
join user_high u on u.id = gu.user_id
where gu.group_id = #{groupId}
and gu.last_read_message_id >= #{lastReadMessageId}
and gu.user_id != #{userId}
order by gu.last_read_message_id desc
limit #{limit}

select gu.user_id as userId,
       gu.role as role,
       u.avatar_url as avatarUrl,
       u.nickname as nickname
from group_user gu
left join user_high u on u.id = gu.user_id
where gu.group_id = #{groupId}

    and gu.user_id > #{lastId}

order by gu.role desc, gu.user_id asc
limit #{limit}

select g.id as groupId, g.owner_id as ownerId, g.avatar_url as groupAvatarUrl, g.name as groupName, g.signature as signature, g.member_count as memberCount, g.last_message as lastMessage, g.last_message_type as lastMessageType, g.last_message_time as lastMessageTime, g.status as status, g.created_time as createdTime, g.updated_time as updatedTime, gu.unread_count as unreadCount, gu.role as role from `group` g join group_user gu on gu.group_id = g.id and gu.user_id = #{userId}
g.name like CONCAT('%', #{keyword}, '%')
and g.id < #{lastId}
order by g.id desc limit #{limit}

select c.id as conversationId, c.last_message as lastMessage, c.last_message_time as lastMessageTime, c.last_message_type as lastMessageType, case when c.user1_id = #{userId} then c.unread_count_user2 else c.unread_count_user1 end as unreadCount, case when c.user1_id = #{userId} then c.user2_id else c.user1_id end as otherUserId from conversation c join user_high u on u.id = case when c.user1_id = #{userId} then c.user2_id else c.user1_id end where (c.user1_id = #{userId} or c.user2_id = #{userId})
and u.nickname like CONCAT('%', #{keyword}, '%')
and c.id < #{lastId}
order by c.id desc limit #{limit}

select count(*) as count
from group_user
where group_id = #{groupId}

select user_id as userId
from group_user
where group_id = #{groupId}
and user_id in

    #{userId}

select gu.user_id as userId,
       gu.role as role
from group_user gu
where gu.group_id = #{groupId}
  and gu.user_id  = #{userId}
